WITH valid AS (SELECT *, FLOOR(balance) AS balance_whole, ABS(balance) AS abs_balance FROM accounts WHERE opened_date >= TO_DATE('2023-04-23') AND customer_id IS NOT NULL) SELECT d.city, d.segment, COUNT(*) AS cnt, SUM(e.balance) AS total_balance, GROUPING_ID() AS level_id FROM valid e INNER JOIN customers d ON e.customer_id = d.id GROUP BY ROLLUP (d.city, d.segment) ORDER BY total_balance DESC NULLS LAST
